<?php
require 'config.php'; require 'includes/functions.php'; require_login();
$user=current_user();$pageTitle='Post a listing';$activePage='post';$errors=[];
$types=$pdo->query("SELECT id,name FROM listing_types WHERE name IN ('sell','buy') ORDER BY id")->fetchAll();$crops=$pdo->query('SELECT id,name FROM crops ORDER BY name')->fetchAll();$units=$pdo->query('SELECT id,name FROM units ORDER BY name')->fetchAll();$regions=$pdo->query('SELECT id,name FROM regions ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf($_POST['csrf_token']??''))$errors[]='Your session expired. Please try again.';
 $type_id=(int)($_POST['listing_type_id']??0);$crop_id=(int)($_POST['crop_id']??0);$unit_id=(int)($_POST['unit_id']??0);$region_id=(int)($_POST['region_id']??0);$district_id=!empty($_POST['district_id'])?(int)$_POST['district_id']:null;$ward_id=!empty($_POST['ward_id'])?(int)$_POST['ward_id']:null;$village_id=!empty($_POST['village_id'])?(int)$_POST['village_id']:null;$quantity=$_POST['quantity']??'';$price=$_POST['price']??'';$note=trim($_POST['note']??'');
 if($type_id<=0)$errors[]='Choose whether you are selling or buying.';if($crop_id<=0)$errors[]='Choose a crop.';if($unit_id<=0)$errors[]='Choose a unit.';if($region_id<=0)$errors[]='Choose a region.';if(!is_numeric($quantity)||(float)$quantity<=0)$errors[]='Quantity must be greater than zero.';if(!is_numeric($price)||(float)$price<=0)$errors[]='Price must be greater than zero.';
 if(!$errors){$s=$pdo->prepare('SELECT id FROM listing_types WHERE id=? AND name IN (\'sell\',\'buy\')');$s->execute([$type_id]);if(!$s->fetch())$errors[]='Invalid listing type.';$s=$pdo->prepare('SELECT id FROM crops WHERE id=?');$s->execute([$crop_id]);if(!$s->fetch())$errors[]='Invalid crop.';$s=$pdo->prepare('SELECT id FROM units WHERE id=?');$s->execute([$unit_id]);if(!$s->fetch())$errors[]='Invalid unit.';$s=$pdo->prepare('SELECT id FROM regions WHERE id=?');$s->execute([$region_id]);if(!$s->fetch())$errors[]='Invalid region.';}
 if(!$errors&&$district_id!==null){$s=$pdo->prepare('SELECT id FROM districts WHERE id=? AND region_id=?');$s->execute([$district_id,$region_id]);if(!$s->fetch())$errors[]='Invalid district.';}
 if(!$errors&&$ward_id!==null&&$district_id!==null){$s=$pdo->prepare('SELECT id FROM wards WHERE id=? AND district_id=?');$s->execute([$ward_id,$district_id]);if(!$s->fetch())$errors[]='Invalid ward.';}
 if(!$errors&&$village_id!==null&&$ward_id!==null){$s=$pdo->prepare('SELECT id FROM villages WHERE id=? AND ward_id=?');$s->execute([$village_id,$ward_id]);if(!$s->fetch())$errors[]='Invalid village.';}
 if(!$errors){$status_id=lookup_id($pdo,'listing_statuses','active');if(!$status_id)$errors[]='Active listing status is missing.';else{$s=$pdo->prepare('INSERT INTO listings(user_id,listing_type_id,crop_id,unit_id,region_id,district_id,ward_id,village_id,quantity,price,note,status_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$user['id'],$type_id,$crop_id,$unit_id,$region_id,$district_id,$ward_id,$village_id,(float)$quantity,(float)$price,$note?:null,$status_id]);header('Location:marketplace.php?posted=1');exit;}}
}
$sr=(int)($_POST['region_id']??0);$sd=(int)($_POST['district_id']??0);$sw=(int)($_POST['ward_id']??0);$districts=$wards=$villages=[];if($sr){$s=$pdo->prepare('SELECT id,name FROM districts WHERE region_id=? ORDER BY name');$s->execute([$sr]);$districts=$s->fetchAll();}if($sd){$s=$pdo->prepare('SELECT id,name FROM wards WHERE district_id=? ORDER BY name');$s->execute([$sd]);$wards=$s->fetchAll();}if($sw){$s=$pdo->prepare('SELECT id,name FROM villages WHERE ward_id=? ORDER BY name');$s->execute([$sw]);$villages=$s->fetchAll();}
require 'includes/header.php'; ?>
<section class="block top-space"><p class="eyebrow">NEW MARKET LISTING</p><h1>Post a listing</h1><p class="sub-small">Tell buyers or sellers what you have, what you need, and your price.</p></section><section class="block form-shell"><div class="form-card"><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="type-picker"><?php foreach($types as $t): ?><label><input type="radio" name="listing_type_id" value="<?= (int)$t['id'] ?>" <?= ((int)($_POST['listing_type_id']??$types[0]['id'])===(int)$t['id'])?'checked':'' ?>><span><?= $t['name']==='sell'?'I\'m selling':'I\'m buying' ?></span></label><?php endforeach; ?></div><div class="field"><label>Crop</label><select name="crop_id" required><option value="">Choose crop</option><?php foreach($crops as $c): ?><option value="<?= (int)$c['id'] ?>" <?= ((int)($_POST['crop_id']??0)===(int)$c['id'])?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="row2"><div class="field"><label>Quantity</label><input type="number" name="quantity" min="0.001" step="0.001" value="<?= e($_POST['quantity']??'') ?>" required></div><div class="field"><label>Unit</label><select name="unit_id" required><option value="">Choose unit</option><?php foreach($units as $u): ?><option value="<?= (int)$u['id'] ?>" <?= ((int)($_POST['unit_id']??0)===(int)$u['id'])?'selected':'' ?>><?= e($u['name']) ?></option><?php endforeach; ?></select></div></div><div class="field"><label>Price per unit (TZS)</label><input type="number" name="price" min="0.01" step="0.01" value="<?= e($_POST['price']??'') ?>" required></div><div class="field"><label>Region</label><select name="region_id" required><option value="">Choose region</option><?php foreach($regions as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $sr===(int)$r['id']?'selected':'' ?>><?= e($r['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>District <small>(optional)</small></label><select name="district_id"><option value="">Choose district</option><?php foreach($districts as $d): ?><option value="<?= (int)$d['id'] ?>" <?= $sd===(int)$d['id']?'selected':'' ?>><?= e($d['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Ward <small>(optional)</small></label><select name="ward_id"><option value="">Choose ward</option><?php foreach($wards as $w): ?><option value="<?= (int)$w['id'] ?>" <?= $sw===(int)$w['id']?'selected':'' ?>><?= e($w['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Village <small>(optional)</small></label><select name="village_id"><option value="">Choose village</option><?php foreach($villages as $v): ?><option value="<?= (int)$v['id'] ?>" <?= ((int)($_POST['village_id']??0)===(int)$v['id'])?'selected':'' ?>><?= e($v['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Notes <small>(optional)</small></label><textarea name="note" rows="5" placeholder="Quality, delivery, availability..."><?= e($_POST['note']??'') ?></textarea></div><?php foreach($errors as $err): ?><div class="error"><?= e($err) ?></div><?php endforeach; ?><button class="btn full" type="submit">Publish listing</button></form></div><aside class="side-note"><h3>Before you post</h3><p>Your name and phone number will be visible on the marketplace.</p><ul><li>Use a realistic price.</li><li>Describe quality and availability.</li><li>Agree inspection, transport and payment directly.</li></ul></aside></section>
